-- Thin union of the 16 per-line batches that actually do this grain's
-- aggregation (int_line_stops_real_real_b0.sql .. _b15.sql, generated by
-- dbt/scripts/generate_line_stops_batches.py). Batching by `line` -- part
-- of every grain's GROUP BY key -- fixes a repeated full-host OOM (see
-- docs/ROADMAP.md's 1.1.1 entry) without changing this model's output:
-- `line` being part of the key means two rows sharing a full group key
-- always land in the same batch, so each batch's aggregate is already
-- final for the groups it contains and this union needs no
-- re-aggregation.
--
-- Kept under this exact model name so every downstream ref() -- this
-- grain's three siblings and line_stops.sql's own union -- needs zero
-- changes. Still contract-enforced so a batch drifting from the 8-column
-- shape is still a compile-time error, not a silent one.
--
-- This grain: real operator, real day_type. Drops rows with no operator at
-- all (everything before 2026-09-12) rather than grouping them under a
-- literal NULL -- a NULL-operator "real" grain would never be looked up by
-- anything, since a live bus either reports a real operator (and would
-- look for that) or none (and the API skips straight to the '*' rungs).
select * from (
    select * from {{ ref('int_line_stops_real_real_b0') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b1') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b2') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b3') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b4') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b5') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b6') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b7') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b8') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b9') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b10') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b11') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b12') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b13') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b14') }}
    union all
    select * from {{ ref('int_line_stops_real_real_b15') }}
)
